"""
Generalized RAG Evaluation Harness Template

Multi-metric evaluation framework with tension-preserving synthesis.
Replace placeholders ({{...}}) with your project-specific values.

Source patterns:
- DSPy Evaluate (dspy/evaluate/evaluate.py)
- DSPy metrics (dspy/evaluate/metrics.py, auto_evaluation.py)
- LegendMentor multi-perspective review/synthesis pattern
"""

from dataclasses import dataclass, field
from typing import Callable


# --- Test Case Structure ---

@dataclass
class RAGTestCase:
    query: str
    expected_answer: str
    expected_sources: list[str]
    category: str = ""          # e.g., "factoid", "multi-hop", "analytical"
    difficulty: str = "medium"  # easy | medium | hard
    metadata: dict = field(default_factory=dict)


# --- Metric Definitions ---

@dataclass
class MetricResult:
    name: str
    score: float        # 0.0 to 1.0
    explanation: str
    details: dict = field(default_factory=dict)


def retrieval_precision(test_case: RAGTestCase, retrieved_chunks: list[dict]) -> MetricResult:
    """What fraction of retrieved chunks are relevant?"""
    if not retrieved_chunks:
        return MetricResult(name="retrieval_precision", score=0.0, explanation="No chunks retrieved")

    relevant_count = sum(
        1 for chunk in retrieved_chunks
        if any(src in chunk.get("source", "") for src in test_case.expected_sources)
    )
    score = relevant_count / len(retrieved_chunks)
    return MetricResult(
        name="retrieval_precision",
        score=score,
        explanation=f"{relevant_count}/{len(retrieved_chunks)} chunks from expected sources",
    )


def retrieval_recall(test_case: RAGTestCase, retrieved_chunks: list[dict]) -> MetricResult:
    """What fraction of expected sources appear in retrieved chunks?"""
    if not test_case.expected_sources:
        return MetricResult(name="retrieval_recall", score=1.0, explanation="No expected sources specified")

    found = set()
    for chunk in retrieved_chunks:
        for src in test_case.expected_sources:
            if src in chunk.get("source", ""):
                found.add(src)

    score = len(found) / len(test_case.expected_sources)
    return MetricResult(
        name="retrieval_recall",
        score=score,
        explanation=f"{len(found)}/{len(test_case.expected_sources)} expected sources found",
    )


def groundedness(test_case: RAGTestCase, answer: str, context: list[dict]) -> MetricResult:
    """Is the answer supported by the retrieved context?"""
    # {{Replace with your LLM-as-judge implementation}}
    # Prompt pattern:
    #   "Given the context below, is the following answer fully supported?
    #    Context: {context}
    #    Answer: {answer}
    #    Score 0-1 where 1 = fully grounded, 0 = hallucinated.
    #    Explain which claims are/aren't supported."
    raise NotImplementedError("Implement with LLM-as-judge")


def answer_relevance(test_case: RAGTestCase, answer: str) -> MetricResult:
    """Does the answer address the query?"""
    # {{Replace with your LLM-as-judge or embedding similarity implementation}}
    raise NotImplementedError("Implement with LLM-as-judge")


def faithfulness(test_case: RAGTestCase, answer: str, expected: str) -> MetricResult:
