    #   - Semantic similarity via embeddings (flexible, may miss nuance)
    #   - LLM-as-judge comparison (most flexible, most expensive)
    raise NotImplementedError("Implement comparison logic")


# --- Evaluation Runner ---

@dataclass
class EvaluationResult:
    test_case: RAGTestCase
    metrics: list[MetricResult]
    tensions: list[str]  # Documented disagreements between metrics


@dataclass
class AggregateResults:
    total_cases: int
    per_metric_averages: dict[str, float]
    per_category_averages: dict[str, dict[str, float]]
    tensions: list[str]
    worst_cases: list[EvaluationResult]


def detect_tensions(metrics: list[MetricResult]) -> list[str]:
    """
    Identify tensions between metrics for a single test case.

    Tension = two metrics disagree significantly (>0.3 difference).
    These are the most informative signals for system improvement.
    """
    tensions = []
    threshold = 0.3

    tension_interpretations = {
        ("retrieval_precision", "retrieval_recall"):
            "High precision + low recall: retrieving relevant chunks but missing some. Consider increasing top_k.",
        ("retrieval_recall", "retrieval_precision"):
            "High recall + low precision: finding all sources but including noise. Consider adding reranking.",
        ("groundedness", "answer_relevance"):
            "High groundedness + low relevance: answer is supported by context but doesn't address the question. Check retrieval alignment.",
        ("answer_relevance", "groundedness"):
            "High relevance + low groundedness: answer addresses the question but includes unsupported claims. Tighten generation constraints.",
        ("groundedness", "faithfulness"):
            "High groundedness + low faithfulness: answer is context-supported but doesn't match expected answer. Check if expected answer needs context not in the corpus.",
    }

    for i, m1 in enumerate(metrics):
        for m2 in metrics[i + 1:]:
            diff = abs(m1.score - m2.score)
            if diff >= threshold:
                key = (m1.name, m2.name) if m1.score > m2.score else (m2.name, m1.name)
                interpretation = tension_interpretations.get(
                    key,
                    f"{key[0]} ({key[1]} scored higher) vs {key[1]}: investigate why these disagree.",
                )
                tensions.append(interpretation)

    return tensions


def run_evaluation(
    test_cases: list[RAGTestCase],
    pipeline_fn: Callable,
    metrics: list[Callable] | None = None,
) -> AggregateResults:
    """
    Run the evaluation harness across all test cases.

    Args:
        test_cases: List of RAGTestCase instances
        pipeline_fn: Function(query) -> {answer, chunks, context}
        metrics: List of metric functions (defaults to all defined above)
    """
    results = []

    for case in test_cases:
        # Run pipeline
        output = pipeline_fn(case.query)

        # Compute metrics
        case_metrics = [
            retrieval_precision(case, output.get("chunks", [])),
            retrieval_recall(case, output.get("chunks", [])),
            groundedness(case, output.get("answer", ""), output.get("context", [])),
            answer_relevance(case, output.get("answer", "")),
            faithfulness(case, output.get("answer", ""), case.expected_answer),
        ]

        # Detect tensions
        tensions = detect_tensions(case_metrics)

        results.append(EvaluationResult(
            test_case=case,
            metrics=case_metrics,
            tensions=tensions,
        ))

    # Aggregate
    per_metric = {}
    per_category: dict[str, dict[str, list[float]]] = {}

    for r in results:
        for m in r.metrics:
            per_metric.setdefault(m.name, []).append(m.score)
            cat = r.test_case.category or "uncategorized"
            per_category.setdefault(cat, {}).setdefault(m.name, []).append(m.score)

    all_tensions = []
    for r in results:
        all_tensions.extend(r.tensions)

    # Deduplicate tensions by keeping unique interpretations
    unique_tensions = list(dict.fromkeys(all_tensions))

    # Find worst cases (lowest average metric score)
    results_with_avg = [
        (r, sum(m.score for m in r.metrics) / len(r.metrics))
        for r in results
    ]
    results_with_avg.sort(key=lambda x: x[1])
    worst = [r for r, _ in results_with_avg[:5]]

    return AggregateResults(
        total_cases=len(test_cases),
        per_metric_averages={k: sum(v) / len(v) for k, v in per_metric.items()},
        per_category_averages={
            cat: {k: sum(v) / len(v) for k, v in metrics_dict.items()}
            for cat, metrics_dict in per_category.items()
        },
        tensions=unique_tensions,
        worst_cases=worst,
    )

